export function parseArgs(argv: string[]): OpenOptions {
	const options: OpenOptions = {
		port: BROWSER_DEFAULTS.port,
		url: BROWSER_DEFAULTS.url,
		urlExplicit: false,
		headless: false,
		status: false,
		minimize: true,
		park: true,
		flash: false,
		dryRun: false,
		json: false,
		clean: false,
		keepExtensions: false,
		loadTimeoutMs: 15_000,
		android: false,
		record: false,
		recordFrames: null,
		browserArgs: [],
		locale: process.env.BROWSER_LOCALE?.trim() || DEFAULT_LOCALE,
	};

	for (let i = 0; i < argv.length; i++) {
		switch (argv[i]) {
			case "--port":
				options.port = +(argv[++i] ?? die("Usage: --port <N>"));
				break;
			case "--url":
				options.url = argv[++i] ?? die("Usage: --url <url>");
				options.urlExplicit = true;
				break;
			case "--user-data":
				options.userDataDir = argv[++i] ?? die("Usage: --user-data <dir>");
				break;
			case "--clean":
				options.clean = true;
				break;
			case "--load-timeout": {
				const secs = +(argv[++i] ?? die("Usage: --load-timeout <seconds>"));
				if (!Number.isFinite(secs) || secs < 0) die("Usage: --load-timeout <seconds>");
				options.loadTimeoutMs = secs * 1000;
				break;
			}
			case "--session":
				options.session = argv[++i] ?? die("Usage: --session <name>");
				break;
			case "--binary":
				options.binary = argv[++i] ?? die("Usage: --binary <path>");
				break;
			case "--headless":
				options.headless = true;
				break;
			case "--android":
				options.android = true;
				break;
			case "--record":
				options.record = true;
				if (argv[i + 1] && !argv[i + 1].startsWith("--")) {
					const frames = +(argv[i + 1] ?? "");
					if (!Number.isInteger(frames) || frames <= 0)
						die("Usage: --record [N]");
					options.recordFrames = frames;
					i += 1;
				}
				break;
			case "--status":
				options.status = true;
				break;
			case "--load-extension":
				options.loadExtension =
					argv[++i] ?? die("Usage: --load-extension <dir>");
				break;
			case "--keep-extensions":
				options.keepExtensions = true;
				break;
			case "--browser-arg":
				options.browserArgs.push(
					argv[++i] ?? die("Usage: --browser-arg <arg>"),
				);
				break;
			case "--locale":
				options.locale = argv[++i] ?? die("Usage: --locale <bcp47>");
				break;
			case "--minimize":
				options.minimize = true;
				options.park = false;
				break;
			case "--background":
				options.minimize = true;
				options.park = true;
				break;
			case "--normal":
			case "--no-minimize":
				options.minimize = false;
				options.park = false;
				break;
			case "--flash":
				options.flash = true;
				break;
			case "--dry-run":
				options.dryRun = true;
				break;
			case "--json":
				options.json = true;
				break;
--- extargs
 * run's browser on that port is left alone and a free port is used instead.
 */
export async function ownsBrowserOn(
	port: number,
	options: Pick<OpenOptions, "clean" | "userDataDir">,
): Promise<boolean> {
	if (options.clean) return false;
	const dir = options.userDataDir ?? resolveDefaultProfileDir(port);
	if (dir === globalProfileDir(port)) return true;
	const info = await readLaunchInfo(dir).catch(() => null);
	if (!info?.pid || info.port !== port || !processExists(info.pid)) return false;
	return (await processMatchesLaunchInfo({ pid: info.pid, port, userDataDir: dir })) !== false;
}

/**
 * A run that loads an extension starts with only that one: a force-installed
 * blocker (a managed policy) holds a site's subresources until its own filter
 * lists settle, which left the tab on about:blank or "loading" forever.
 *
 * A run that loads none keeps the profile's extensions, because they are the
 * reason it pointed at that profile — a signed-in Tampermonkey on port 12345
 * is the tool being driven, not noise. Headless runs stay bare by default
 * (`--disable-extensions`), as before. `--keep-extensions` opts a
 * `--load-extension` run back into the profile's extensions too.
 */
export function extensionArgs(
	options: Pick<OpenOptions, "loadExtension" | "keepExtensions" | "headless">,
): string[] {
	const args: string[] = [];
	if (options.loadExtension) args.push(`--load-extension=${options.loadExtension}`);
	if (options.keepExtensions) return args;
	if (options.loadExtension) args.push(`--disable-extensions-except=${options.loadExtension}`);
	else if (options.headless) args.push("--disable-extensions");
	return args;
}

/** The live pid holding Chromium's SingletonLock (a `<host>-<pid>` symlink) on a profile, if any. */
export function profileHolderPid(userDataDir: string): number | null {
	try {
		const target = readlinkSync(join(userDataDir, "SingletonLock"));
		const pid = Number(target.slice(target.lastIndexOf("-") + 1));
		return Number.isInteger(pid) && pid > 0 && processExists(pid) ? pid : null;
	} catch {
		return null;
	}
}

async function buildOpenPlan(
	requestedPort: number,
	owns: (port: number) => Promise<boolean> = async () => true,
): Promise<OpenPlan> {
	const requested = await resolvePortState(requestedPort);
	if (requested.lock) {
		const actualPort = await findAvailablePort(requestedPort + 1);
		return {
			requestedPort,
			actualPort,
			browserAction: "launch-new-browser",
			portNote: `Requested port ${requestedPort} is locked by another browser session, so Chrome will use ${actualPort}.`,
			lockStatus: requested.lockStatus,
		};
	}

	if (requested.browserReachable && !(await owns(requestedPort))) {
		const actualPort = await findAvailablePort(requestedPort + 1);
		return {
			requestedPort,
			actualPort,
			browserAction: "launch-new-browser",
			portNote: `Port ${requestedPort} has another profile's browser, so Chrome will use ${actualPort}.`,
			lockStatus: requested.lockStatus,

	})();`;
}

/** Applied on the focused tab, whether the browser was launched or attached to. */
export async function configureAndroidTab(cdp: CDP) {
	await cdp.send("Emulation.setDeviceMetricsOverride", ANDROID_DEVICE_METRICS);
	await cdp.send("Emulation.setTouchEmulationEnabled", {
		enabled: true,
		maxTouchPoints: 5,
	});
