/** Build the `--load-extension` value and, where the profile must be isolated, the matching except list. */
export function extensionArgs(
	options: Pick<
		OpenOptions,
		"loadExtension" | "keepExtensions" | "headless" | "selectorDir"
	>,
): string[] {
	const dirs = mergeExtensionDirs(options.loadExtension, options.selectorDir);
	const args: string[] = [];
	if (dirs) args.push(`--load-extension=${dirs}`);
	if (options.keepExtensions) return args;
	if (options.loadExtension) args.push(`--disable-extensions-except=${dirs}`);
	else if (options.headless) {
		args.push(dirs ? `--disable-extensions-except=${dirs}` : "--disable-extensions");
	}
	return args;
}

const DEV_SELECTOR_BUILDS = ["chrome-mv3", "chrome-mv3-dev"];

/**
 * The Dev Selector build to load: the newest `.output/chrome-mv3*` directory that
 * has a manifest. A project that has not built one gets an error that names the
 * paths it looked at instead of a Chromium flag pointing nowhere.
 */
export function resolveDevSelectorDir(root: string): string {
	const outputDir = join(root, ".output");
	let newest: { dir: string; mtimeMs: number } | null = null;
	for (const name of DEV_SELECTOR_BUILDS) {
		const dir = join(outputDir, name);
		try {
			const stat = statSync(join(dir, "manifest.json"));
			if (!stat.isFile()) continue;
			if (!newest || stat.mtimeMs > newest.mtimeMs) newest = { dir, mtimeMs: stat.mtimeMs };
		} catch {
			// Not built (or not a directory): try the next candidate.
		}
	}
	if (!newest) {
		throw new Error(
			`Dev Selector build not found: expected ${DEV_SELECTOR_BUILDS.map((name) => join(outputDir, name)).join(" or ")}`,
		);
	}
	return newest.dir;
}

